import {renderTodayView} from './today.js';
import {civilDate,addDays,completed,dailyChoice,dayRule,forecast,recordOutcome,elapsed,validateBackup,deadlineRisks} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={today:'◉',calendar:'▦',roadmap:'⌘',history:'↶',settings:'⚙'};
let state,db,view='today',search='',filter='active',selectedOutcome='',lastDate='',offlineReady=false;
const uid=()=>crypto.randomUUID();
function today(){return civilDate(new Date(),state.settings.timezone);}
function pretty(day,opts={weekday:'long',month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',...opts}).format(new Date(day+'T12:00:00Z'));}
function safeLink(link){try{const u=new URL(link);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function modal(html){const d=$('#modal');d.innerHTML=html;d.showModal();d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());}
function fatal(message){$('#app').innerHTML=`<div class="fatal"><h1>Your study space could not open</h1><p>${esc(message)}</p><p>Your existing data has not been replaced. Try a regular browser window with storage enabled.</p><button onclick="location.reload()">Try again</button></div>`;}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('ensam-learning-os',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function readDB(){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly'),r=tx.objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function commit(change){
  try{
    const updated=await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state'),r=store.get('main');let next;
      r.onsuccess=()=>{try{const current=r.result??state;if(current.revision!==state.revision)throw new Error('Another tab changed your plan. Refresh this page before making another change.');next=change(structuredClone(current));next.revision=current.revision+1;next.updatedAt=new Date().toISOString();store.put(next,'main');}catch(e){tx.abort();reject(e);}};
      tx.oncomplete=()=>resolve(next);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('The change could not be saved.'));});
    state=updated;channel.postMessage('changed');render();return true;
  }catch(e){toast(e.message||'Could not save. Your previous data is safe.');return false;}
}
const channel=new BroadcastChannel('ensam-state');channel.onmessage=async()=>{state=await readDB();render();toast('Updated from your other tab.');};
async function boot(){
  try{db=await openDB();state=await readDB();if(!state){state=await fetch('./seed.json').then(r=>{if(!r.ok)throw Error('The initial curriculum could not load.');return r.json();});if(!await commit(x=>x))throw Error('Initial data could not be saved. Enable browser storage and retry.');}else validateBackup(state);render();
    if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;render();}).catch(()=>{});}
    navigator.storage?.persist?.().catch(()=>{});
  }catch(e){fatal(e.message);}
}
function nav(){return `<aside class="sidebar"><a class="brand" data-view="today" href="#today" aria-label="Learning OS home"><span class="brand-mark">≡</span><span>learning<span class="brand-serif">os</span><small>ENSAM · ML SYSTEMS</small></span></a><div class="workspace-label">YOUR STUDY SPACE</div><nav>${[['today','Today'],['calendar','Calendar'],['roadmap','Curriculum'],['history','Study log'],['settings','Settings']].map(([id,label])=>`<button data-view="${id}" class="nav-item ${view===id?'active':''}"><span>${icons[id]}</span>${label}${view===id?'<i></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="small-orbit">↗</div><p>Small steps.<br><span>Long horizons.</span></p><div class="local-status"><b></b> Saved on this browser</div><small>Personal workspace · MVP 0.2.1</small></div></aside>`;}
function render(){if(!state)return;document.body.dataset.view=view;lastDate=today();$('#app').innerHTML=`${nav()}<main><header class="topbar"><span>Personal learning / <b>${({today:'Today',calendar:'Calendar',roadmap:'Curriculum',history:'Study log',settings:'Settings'})[view]}</b></span><div class="top-right"><span class="connection">${navigator.onLine?'● Local-first':'◌ Offline'}</span><span class="avatar">R</span></div></header><div class="content">${({today:renderToday,calendar:renderCalendar,roadmap:renderRoadmap,history:renderHistory,settings:renderSettings})[view]()}</div><footer>Learn with intention. Leave room for life.<span>${esc(state.settings.timezone)} · ${offlineReady?'Offline ready':'Local storage active'}</span></footer></main>`;bind();tick();}
function renderToday(){return renderTodayView(state,today());}
function renderCalendar(){const plan=forecast(state,today(),14);return `<div class="page-heading compact"><div><p class="eyebrow">THE NEXT TWO WEEKS</p><h1>Structure, <em>with breathing room.</em></h1><p class="subtitle">Proposed study blocks. They move when life does.</p></div><button class="secondary" data-action="new">+ Add a task</button></div><div class="calendar-list">${plan.map(p=>`<article class="calendar-row ${p.day===today()?'is-today':''}"><div class="calendar-date"><small>${esc(pretty(p.day,{weekday:'short'}))}</small><b>${p.day.slice(-2)}</b></div><div class="calendar-content"><span class="tiny-label">${p.task?(p.task.track==='academic'?'ENSAM':'INDEPENDENT STUDY'):p.kind==='rest'?'RECOVERY':'FLEXIBLE'}</span><h3>${esc(p.task?p.task.resource+' '+p.task.section+' · '+p.task.heading:p.reason)}</h3><p>${esc(p.task?p.task.action:'Your unfinished work stays safe.')}</p></div><span class="row-time">${p.task?p.minutes+' min · estimate':'—'}</span><button class="icon-button" data-day="${p.day}" aria-label="Adjust ${p.day}">⋯</button></article>`).join('')}</div><h2 class="section-title">Academic dates</h2><p class="muted">Calendar windows are distinct from your individual exam timetable. Resits stay conditional.</p><div class="event-grid">${state.calendar.map(e=>`<article class="event-card"><span class="tiny-label">${e.kind==='exam_prep'?'PERSONAL SETTING':e.kind==='readiness'?'YOUR TARGET':e.active?'ACADEMIC CALENDAR':'CONDITIONAL'}</span><h3>${esc(e.title)}</h3><p>${esc(pretty(e.start_date,{day:'numeric',month:'short',year:'numeric'}))}${e.start_date!==e.end_date_inclusive?' – '+esc(pretty(e.end_date_inclusive,{day:'numeric',month:'short'})):''}</p><button class="text-button" data-event="${esc(e.id)}">${e.active?'Edit dates':'Enable / edit'} →</button></article>`).join('')}</div>`;}
function renderRoadmap(){const done=completed(state);const tasks=state.tasks.filter(t=>!t.archived&&(filter==='all'||(filter==='active'?t.status==='active'&&!done.has(t.id):filter==='completed'?done.has(t.id):t.status==='draft'))&&(`${t.title} ${t.resource}`.toLowerCase().includes(search.toLowerCase())));return `<div class="page-heading compact"><div><p class="eyebrow">YOUR LIVING CURRICULUM</p><h1>A steady <em>direction.</em></h1><p class="subtitle">Edit the route. Keep the learning.</p></div><button class="primary" data-action="new">+ Add task</button></div><div class="phase-strip">${['S1 · Foundations','S2 · Probability','S3 · Classical ML','S4 · Deep learning','S5 · One capstone','S6 · PFE'].map((s,i)=>`<div class="${i===0?'current':''}"><small>${i===0?'CURRENT':'TENTATIVE'}</small>${s}</div>`).join('')}</div><div class="library-toolbar"><div class="tabs">${['active','draft','completed','all'].map(x=>`<button data-filter="${x}" class="${x===filter?'selected':''}">${x==='draft'?'Research library':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><input id="search" aria-label="Search curriculum" placeholder="Search topics or resources…" value="${esc(search)}"></div><p class="muted small">${filter==='draft'?'Research tasks need review before activation. Notes show what you recorded, not automatic mastery.':'Only active tasks enter your schedule. Estimated effort can be edited.'}</p><div class="task-list">${tasks.length?tasks.slice(0,80).map(t=>`<article class="task-row"><span class="task-bullet ${done.has(t.id)?'done':''}">${done.has(t.id)?'✓':t.status==='draft'?'·':'○'}</span><div><span class="tiny-label">${esc(t.resource)} · ${t.status==='draft'?'DRAFT':t.track==='academic'?'ENSAM':'ACTIVE'}</span><h3>${esc(t.section+' '+t.heading)}</h3><p>${esc(t.action)}</p></div><span class="row-time">${t.minutes} min<br><small>estimate</small></span><button class="text-button" data-edit="${esc(t.id)}">Review →</button></article>`).join(''):'<div class="empty">No tasks here. Your work is safely recorded in the study log.</div>'}</div>${tasks.length>80?'<p class="muted">Showing 80 matching tasks. Use search to find a specific topic.</p>':''}`;}
function renderHistory(){const voided=new Set(state.events.filter(e=>e.type==='void').map(e=>e.target)),events=state.events.filter(e=>e.type==='session').slice().reverse();return `<div class="page-heading compact"><div><p class="eyebrow">EVIDENCE, NOT STREAKS</p><h1>The work <em>you’ve done.</em></h1><p class="subtitle">Every attempt counts as history. Completion stays explicit.</p></div><button class="secondary" data-action="export">Export backup ↗</button></div><div class="checkpoint-banner">✓ ILA §2.9 examples completed · §3.1 planned for 16 Nov 2026 <small>User-confirmed checkpoint, separate from session history.</small></div>${events.length?events.map(e=>{const t=e.taskSnapshot||state.tasks.find(t=>t.id===e.taskId);return `<article class="log-row ${voided.has(e.id)?'voided':''}"><span class="outcome-badge ${e.outcome}">${esc(e.outcome)}</span><div><h3>${esc(t?.resource)} ${esc(t?.section)} · ${esc(t?.heading)}</h3><p>${esc(pretty(e.day))} · ${Math.round(e.minutes)} active min${e.note?' · '+esc(e.note):''}</p></div>${voided.has(e.id)?'<small>Corrected · retained</small>':`<button class="text-button" data-undo="${esc(e.id)}">Correct</button>`}</article>`;}).join(''):'<div class="empty large"><span>↶</span><h2>Your story starts here.</h2><p>Record a completed, partial, ENSAM override or skipped session.<br>No streak to protect. No lost progress.</p><button class="secondary" data-view="today">Back to Today</button></div>'}`;}
function renderSettings(){return `<div class="page-heading compact"><div><p class="eyebrow">MAKE ROOM FOR REAL LIFE</p><h1>Your pace. <em>Your rules.</em></h1><p class="subtitle">A ceiling on study time is permission to stop.</p><p class="small muted">LearningOS v0.2.1 · local browser storage</p></div></div><form id="settings-form" class="settings-grid"><section class="panel"><h2>Study rhythm</h2><label>Focus minutes<input name="focusMinutes" type="number" min="1" max="120" value="${state.settings.focusMinutes}" required></label><label>Break minutes<input name="breakMinutes" type="number" min="1" max="30" value="${state.settings.breakMinutes}" required></label><label>Weekday minutes<input name="dailyMinutes" type="number" min="25" max="150" value="${state.settings.dailyMinutes}" required></label><label>Saturday minutes<input name="saturdayMinutes" type="number" min="25" max="240" value="${state.settings.saturdayMinutes}" required></label><label>Weekly self-study ceiling (hours)<input name="weeklyHours" type="number" min="0" max="20" step="0.5" value="${state.settings.weeklyMinutes/60}" required></label><p class="small muted">Sunday stays free. Friday is overflow or rest. Academic study has its own time; it doesn’t consume the independent-study ceiling.</p></section><section class="panel"><h2>Protection & availability</h2><label>Study timezone<select name="timezone">${['Africa/Casablanca','UTC','Europe/Paris'].map(x=>`<option ${x===state.settings.timezone?'selected':''}>${x}</option>`).join('')}</select></label><label>Exam protection<select name="examMode">${[['auto','Follow calendar'],['on','Always protect for ENSAM'],['off','Off — keep independent study']].map(([v,t])=>`<option value="${v}" ${v===state.settings.examMode?'selected':''}>${t}</option>`).join('')}</select></label><label class="checkbox"><input name="paused" type="checkbox" ${state.settings.paused?'checked':''}> Pause independent roadmap</label><p class="small muted">Exam preparation from 7 December is a suggested default. Change its dates in Calendar. Your personal readiness date stays separate from exam week.</p><button class="primary" type="submit">Save preferences</button></section></form><div class="settings-grid"><section class="panel"><h2>Your data, with you.</h2><p class="muted">Sessions save immediately in this browser. Other devices have separate data. Export a backup before changing browsers or clearing storage.</p><div class="button-row"><button class="secondary" data-action="export">Export backup</button><button class="text-button" data-action="import">Restore backup</button></div><p class="small muted">Restore replaces this browser’s plan after a preview. It does not merge device histories.</p></section><section class="panel"><h2>Obsidian checkpoint</h2><p class="muted">Your local vault was checked during setup. This browser does not silently read your computer. Bring in a note when your progress changes.</p><button class="secondary" data-action="note">Review an Obsidian note ↗</button><p class="small muted">A note is context. You confirm the next task; importing a note never completes chapters.</p></section></div>`;}
function focusTask(){return (state.timer&&state.tasks.find(t=>t.id===state.timer.taskId))||dailyChoice(state,today()).task;}
function tick(){if(!state)return;const timer=state.timer,spent=elapsed(timer),limit=(timer?.targetMinutes||state.settings.focusMinutes)*60000,left=Math.max(0,Math.ceil((limit-spent)/1000));if($('#timer-value'))$('#timer-value').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(timer&&left===0&&$('#timer-label')){$('#timer-label').textContent='FOCUS COMPLETE · REVIEW YOUR SESSION';const b=$('.timer-controls .primary');if(b){b.textContent='Review session';b.dataset.action='finish';}}if($('#break-countdown')){const b=Math.max(0,Math.ceil((state.breakUntil-Date.now())/1000));$('#break-countdown').textContent=String(Math.floor(b/60)).padStart(2,'0')+':'+String(b%60).padStart(2,'0');if(b===0)render();}if(today()!==lastDate&&!timer)render();}
async function timerToggle(){const t=focusTask();if(!t)return;await commit(s=>{if(s.timer){s.timer.accumulatedMs=elapsed(s.timer);s.timer.running=!s.timer.running;s.timer.startedAt=Date.now();}else{s.timer={id:uid(),taskId:t.id,startedAt:Date.now(),createdAt:new Date().toISOString(),accumulatedMs:0,running:true,targetMinutes:s.settings.focusMinutes};}return s;});}
async function finishDialog(presetOutcome=''){const t=focusTask();if(!t)return;if(state.timer?.running){const saved=await commit(s=>{s.timer.accumulatedMs=elapsed(s.timer);s.timer.running=false;return s;});if(!saved)return;}selectedOutcome=presetOutcome;modal(`<form id="outcome-form"><p class="eyebrow">CLOSE THE LOOP</p><h2>How did it go?</h2><p class="muted">${esc(t.resource+' '+t.section+' · '+t.heading)}</p><div class="outcome-grid">${[['completed','✓','Completed','I met the milestone'],['partial','◔','Partial','I made progress'],['ensam','⌘','ENSAM override','Coursework came first'],['skipped','↷','Skipped','Not available today']].map(([v,i,h,d])=>`<label><input type="radio" name="outcome" value="${v}" ${selectedOutcome===v?'checked':''} required><span>${i}</span><b>${h}</b><small>${d}</small></label>`).join('')}</div><label>What did you demonstrate or leave unfinished?<textarea name="note" placeholder="A result, a blocker, or the next step…" rows="3" maxlength="2000"></textarea></label><label>Remaining minutes, if partial (estimate)<input name="remaining" type="number" min="1" max="10000" placeholder="Optional"></label><p class="small muted">${Math.round(elapsed(state.timer)/60000)} active minutes recorded. A completed outcome means you met the task’s milestone.</p><div class="dialog-actions"><button type="button" class="text-button" data-close>Back</button><button class="primary">Save session</button></div></form>`);$('#outcome-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),event={id:state.timer?.id||uid(),taskId:t.id,day:today(),at:new Date().toISOString(),minutes:elapsed(state.timer)/60000,outcome:f.get('outcome'),note:f.get('note'),remainingMinutes:f.get('remaining')?Number(f.get('remaining')):undefined};if(await commit(s=>{const next=recordOutcome(s,event);if(['completed','partial'].includes(event.outcome)&&event.minutes>=1)next.breakUntil=Date.now()+s.settings.breakMinutes*60000;return next;})){$('#modal').close();toast('Session saved. Your roadmap has adapted.');}};}
function editTask(id,preset={}){const editRevision=state.revision;const t=state.tasks.find(t=>t.id===id)||{id:uid(),resource:'ENSAM',section:'',heading:'',action:'',evidence:'',minutes:50,minimumMinutes:25,track:'academic',status:'active',prerequisites:[],order:0,...preset};modal(`<form id="task-form"><p class="eyebrow">${id?'REVIEW & EDIT':'MAKE IT ACTIONABLE'}</p><h2>${id?'Task details':'Add a learning task'}</h2><div class="form-columns"><label>Resource or module<input name="resource" value="${esc(t.resource)}" maxlength="250" required></label><label>Section / chapter<input name="section" value="${esc(t.section)}" maxlength="100" placeholder="§3.1.1 or TD2 · Exercise 3"></label></div><label>Source heading<input name="heading" value="${esc(t.heading)}" maxlength="500" required></label><label>Action<input name="action" value="${esc(t.action)}" maxlength="1000" placeholder="Solve, derive, implement, or explain…" required></label><label>Done when…<textarea name="evidence" maxlength="2000" required>${esc(t.evidence)}</textarea></label><div class="form-columns"><label>Estimated minutes<input name="minutes" type="number" min="1" max="10000" value="${t.minutes}" required></label><label>Priority / track<select name="track"><option value="academic" ${t.track==='academic'?'selected':''}>ENSAM requirement</option><option value="independent" ${t.track==='independent'?'selected':''}>Independent study</option></select></label><label>Start no earlier than<input name="notBefore" type="date" value="${esc(t.notBefore)}"></label><label>Actual deadline (optional)<input name="deadline" type="date" value="${esc(t.deadline)}"></label></div><label>Source link<input name="url" type="url" value="${esc(safeLink(t.url))}" placeholder="https://…"></label><label>Prerequisites <small>Hold Ctrl / Cmd to select more than one</small><select name="prerequisites" multiple size="4">${state.tasks.filter(x=>x.id!==t.id&&!x.archived).map(x=>`<option value="${esc(x.id)}" ${(t.prerequisites||[]).includes(x.id)?'selected':''}>${esc(x.resource+' '+x.section+' · '+x.heading)}</option>`).join('')}</select></label><label>Status<select name="status"><option value="active" ${t.status==='active'?'selected':''}>Active — include in schedule</option><option value="draft" ${t.status==='draft'?'selected':''}>Draft — keep out of schedule</option></select></label><p class="small muted">${esc(t.provenance||'Your authored task. Estimates are adjustable.')} Editing keeps previous revisions and study history. Saving a completed task creates a new follow-up, preserving its original completion.</p><div class="dialog-actions">${id?'<button type="button" class="text-button danger" id="archive-task">Archive task</button>':''}<button type="button" class="text-button" data-close>Cancel</button><button class="primary">Save task</button></div></form>`);$('#task-form').onsubmit=async e=>{e.preventDefault();const taskForm=new FormData(e.target);const f=Object.fromEntries(taskForm);if(state.revision!==editRevision){toast('Your plan changed while this editor was open. Reopen the task to keep the latest changes.');return;}if(state.timer?.taskId===id){toast('Finish the active session before editing this task.');return;}const next={...t,...f,prerequisites:taskForm.getAll('prerequisites'),minutes:Number(f.minutes),minimumMinutes:Math.min(25,Number(f.minutes)),remainingMinutes:undefined,title:f.resource+' '+f.section+' '+f.heading+' — '+f.action};if(await commit(s=>{if(id)s.revisions.push({id:uid(),at:new Date().toISOString(),task:structuredClone(s.tasks.find(x=>x.id===id))});if(id&&completed(s).has(id)){s.tasks.find(x=>x.id===id).archived=true;s.tasks.push({...next,id:uid(),provenance:'Follow-up to a completed task. Previous completion and history preserved.'});}else{s.tasks=id?s.tasks.map(x=>x.id===id?next:x):[...s.tasks,next];}validateBackup(s);return s;})){$('#modal').close();toast('Curriculum saved. Session history kept.');}};$('#archive-task')?.addEventListener('click',async()=>{if(state.timer?.taskId===id){toast('Finish the session before archiving its task.');return;}if(await commit(s=>{s.revisions.push({id:uid(),at:new Date().toISOString(),task:structuredClone(s.tasks.find(x=>x.id===id))});s.tasks.find(x=>x.id===id).archived=true;return s;})){$('#modal').close();toast('Task archived; history preserved.');}});}
function adjustDay(day){modal(`<p class="eyebrow">${esc(pretty(day))}</p><h2>Make room.</h2><p class="muted">Change this day without losing any learning.</p><div class="day-options"><button class="secondary" data-kind="ensam">⌘ ENSAM takes priority</button><button class="secondary" data-kind="rest">☾ Protect a rest day</button><button class="text-button" data-kind="normal">Use normal availability</button></div><button class="text-button" data-close>Close</button>`);document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=async()=>{if(state.timer?.running){toast('Pause and finish your session before changing today.');return;}if(await commit(s=>{s.overrides=s.overrides.filter(o=>o.day!==day);if(b.dataset.kind!=='normal')s.overrides.push({id:uid(),day,kind:b.dataset.kind});return s;})){$('#modal').close();toast('Availability updated. No catch-up debt.');}});}
function editEvent(id){const t=state.calendar.find(c=>c.id===id);modal(`<form id="event-form"><p class="eyebrow">ACADEMIC WINDOW</p><h2>${esc(t.title)}</h2><p class="small muted">${esc(t.provenance||'Uploaded 2026–27 academic calendar. Subject to newer notices.')}</p><label>Start date<input name="start" type="date" value="${t.start_date}" required></label><label>End date (inclusive)<input name="end" type="date" value="${t.end_date_inclusive}" required></label><label class="checkbox"><input type="checkbox" name="active" ${t.active?'checked':''}> Enable this window</label><div class="dialog-actions"><button type="button" data-close class="text-button">Cancel</button><button class="primary">Save dates</button></div></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('start')>f.get('end')){toast('End date must follow the start date.');return;}if(await commit(s=>{const c=s.calendar.find(x=>x.id===id);s.revisions.push({id:uid(),at:new Date().toISOString(),calendar:structuredClone(c)});Object.assign(c,{start_date:f.get('start'),end_date_inclusive:f.get('end'),active:f.has('active'),provenance:'Dates edited by you; prior revision retained.'});return s;}))$('#modal').close();};}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='learning-os-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.');}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>15000000)throw Error('Backup is too large.');const next=validateBackup(JSON.parse(await file.text()));modal(`<p class="eyebrow">RESTORE PREVIEW</p><h2>Restore this study space?</h2><p>${next.tasks.length} tasks · ${next.events.filter(e=>e.type==='session').length} sessions</p><p class="muted">This replaces this browser’s current plan. Export a backup first if you want to keep it. Device histories are not merged.</p><div class="dialog-actions"><button class="text-button" data-close>Cancel</button><button class="secondary" id="pre-export">Export current</button><button class="primary" id="restore">Restore</button></div>`);$('#pre-export').onclick=exportBackup;$('#restore').onclick=async()=>{if(state.timer){toast('Finish the active session before restoring.');return;}if(await commit(s=>({...next,revision:s.revision,timer:null})))$('#modal').close();};}catch(e){toast(e.message);}};input.click();}
function importNote(){modal(`<form id="note-form"><p class="eyebrow">BRING YOUR PROGRESS WITH YOU</p><h2>Review an Obsidian note</h2><p class="muted">Paste a relevant note or choose its Markdown file. It stays in this browser. Review its headings, then choose your next task.</p><label>Markdown file<input id="note-file" type="file" accept=".md,.txt"></label><label>Note content<textarea id="note-text" rows="6" maxlength="200000" placeholder="# Matrix Transformations…"></textarea></label><div id="note-headings"></div><div class="dialog-actions"><button type="button" data-close class="text-button">Close</button><button class="primary">Inspect headings</button></div></form>`);$('#note-file').onchange=async e=>{if(e.target.files[0].size>200000){toast('Choose a note under 200 KB.');return;}$('#note-text').value=await e.target.files[0].text();};$('#note-form').onsubmit=e=>{e.preventDefault();const headings=$('#note-text').value.split('\n').filter(l=>/^#{1,4} /.test(l)).slice(0,20);$('#note-headings').innerHTML=`<p class="small muted">${headings.length} headings found. Notes do not automatically mark material completed.</p><ul class="note-headings">${headings.map(h=>`<li>${esc(h.replace(/^#+ /,''))}</li>`).join('')}</ul><button type="button" id="from-note" class="secondary">Add a task from this note</button>`;$('#from-note').onclick=()=>{$('#modal').close();editTask(null,{resource:'Obsidian note',heading:headings[0]?.replace(/^#+ /,'')||'',provenance:'Manually imported note heading. Progress requires your confirmation.'});};};}
function bind(){document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>finishDialog(b.dataset.outcome));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0);});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTask(b.dataset.edit));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>adjustDay(b.dataset.day));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>editEvent(b.dataset.event));document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{modal(`<h2>Correct this session?</h2><p class="muted">The original stays in your log. Its completion credit will be removed; a follow-up task may become ready again.</p><div class="dialog-actions"><button class="text-button" data-close>Cancel</button><button class="primary" id="confirm-undo">Correct outcome</button></div>`);$('#confirm-undo').onclick=async()=>{if(await commit(s=>{s.events.push({id:uid(),type:'void',target:b.dataset.undo,at:new Date().toISOString()});return s;}))$('#modal').close();};});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='timer')timerToggle();if(a==='end-break')await commit(s=>{s.breakUntil=null;return s;});if(a==='finish')finishDialog();if(a==='new')editTask();if(a==='availability')adjustDay(today());if(a==='export')exportBackup();if(a==='import')importBackup();if(a==='note')importNote();if(a==='early'){const t=forecast(state,today(),14).find(p=>p.task)?.task;if(t)await commit(s=>{s.revisions.push({id:uid(),at:new Date().toISOString(),task:structuredClone(s.tasks.find(x=>x.id===t.id))});s.tasks.find(x=>x.id===t.id).notBefore=today();return s;});}});
  $('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(state.timer){toast('Finish the active session before changing focus settings.');return;}const saved=await commit(s=>{for(const k of ['focusMinutes','breakMinutes','dailyMinutes','saturdayMinutes'])s.settings[k]=Number(f.get(k));s.settings.weeklyMinutes=Number(f.get('weeklyHours'))*60;s.settings.examMode=f.get('examMode');s.settings.timezone=f.get('timezone');s.settings.paused=f.has('paused');validateBackup(s);return s;});if(saved)toast('Your preferences are saved.');});
}
window.addEventListener('online',render);window.addEventListener('offline',render);setInterval(tick,1000);boot();
